#include <vector>

using namespace std;

class Solution {
    int R, C;
    vector<int> parent, size;

    int index(int r, int c) {
        return r * C + c;
    }

    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) {
            parent[rx] = ry;
            size[ry] += size[rx];
        }
    }

    int getSize(int x) {
        return size[find(x)];
    }

public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        R = grid.size();
        C = grid[0].size();
        vector<vector<int>> copy = grid;

        for (auto& h : hits)
            copy[h[0]][h[1]] = 0;

        parent.resize(R * C + 1);
        size.resize(R * C + 1, 1);
        for (int i = 0; i < R * C + 1; ++i)
            parent[i] = i;

        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                if (copy[i][j]) {
                    if (i == 0) unite(index(i, j), R * C);
                    if (i && copy[i - 1][j]) unite(index(i, j), index(i - 1, j));
                    if (j && copy[i][j - 1]) unite(index(i, j), index(i, j - 1));
                }

        vector<int> res(hits.size());
        vector<vector<int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int i = hits.size() - 1; i >= 0; --i) {
            int x = hits[i][0], y = hits[i][1];
            if (!grid[x][y]) continue;
            int before = getSize(R * C);
            int idx = index(x, y);

            copy[x][y] = 1;
            if (x == 0) unite(idx, R * C);
            for (auto& d : dirs) {
                int nx = x + d[0], ny = y + d[1];
                if (nx >= 0 && ny >= 0 && nx < R && ny < C && copy[nx][ny])
                    unite(idx, index(nx, ny));
            }
            int after = getSize(R * C);
            res[i] = max(0, after - before - 1);
        }

        return res;
    }
};
